const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const test = require('node:test');

const {transformers} = require(process.env.CANDIDATE_MODULE);

function withTempDirectory(callback) {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'appium-cli-transformers-'));
  try {
    return callback(directory);
  } finally {
    fs.rmSync(directory, {recursive: true, force: true});
  }
}

test('csv preserves literal parsing and parses regular files, including file symlinks', () => {
  withTempDirectory((directory) => {
    const csvFile = path.join(directory, 'values.csv');
    const csvLink = path.join(directory, 'values-link.csv');
    fs.writeFileSync(csvFile, ' first, second\nthird, , fourth\n');
    fs.symlinkSync(csvFile, csvLink);

    assert.deepEqual(transformers.csv(' first, ,second\nthird'), ['first', 'second\nthird']);
    assert.deepEqual(transformers.csv(csvFile), ['first', 'second', 'third', 'fourth']);
    assert.deepEqual(transformers.csv(csvLink), ['first', 'second', 'third', 'fourth']);
  });
});

test('csv treats directories, missing paths, and dangling symlinks as literals', () => {
  withTempDirectory((directory) => {
    const subdirectory = path.join(directory, 'directory');
    const missing = path.join(directory, 'missing');
    const dangling = path.join(directory, 'dangling');
    fs.mkdirSync(subdirectory);
    fs.symlinkSync(path.join(directory, 'not-there'), dangling);

    assert.deepEqual(transformers.csv(subdirectory), [subdirectory]);
    assert.deepEqual(transformers.csv(missing), [missing]);
    assert.deepEqual(transformers.csv(dangling), [dangling]);
  });
});

test('json preserves JSON parsing and parses regular files, including file symlinks', () => {
  withTempDirectory((directory) => {
    const jsonFile = path.join(directory, 'value.json');
    const jsonLink = path.join(directory, 'value-link.json');
    fs.writeFileSync(jsonFile, '{"fromFile":true}');
    fs.symlinkSync(jsonFile, jsonLink);

    assert.deepEqual(transformers.json('{"literal":true}'), {literal: true});
    assert.deepEqual(transformers.json(jsonFile), {fromFile: true});
    assert.deepEqual(transformers.json(jsonLink), {fromFile: true});
  });
});

test('json treats directories, missing paths, and dangling symlinks as literals', () => {
  withTempDirectory((directory) => {
    const subdirectory = path.join(directory, 'directory');
    const missing = path.join(directory, 'missing');
    const dangling = path.join(directory, 'dangling');
    fs.mkdirSync(subdirectory);
    fs.symlinkSync(path.join(directory, 'not-there'), dangling);

    assert.throws(() => transformers.json(subdirectory), /The provided value must be a valid JSON/);
    assert.throws(() => transformers.json(missing), /The provided value must be a valid JSON/);
    assert.throws(() => transformers.json(dangling), /The provided value must be a valid JSON/);
  });
});

test('filesystem probe errors fall back to literal parsing for both transformers', () => {
  const fsModule = require('node:fs');
  const originalStatSync = fsModule.statSync;
  fsModule.statSync = () => {
    throw new Error('probe failed');
  };
  try {
    assert.deepEqual(transformers.csv('one,two'), ['one', 'two']);
    assert.deepEqual(transformers.json('{"literal":true}'), {literal: true});
  } finally {
    fsModule.statSync = originalStatSync;
  }
});

test('read failures for identified regular files remain argparse errors', () => {
  withTempDirectory((directory) => {
    const fsModule = require('node:fs');
    const originalReadFileSync = fsModule.readFileSync;
    const filePath = path.join(directory, 'read-failure');
    fs.writeFileSync(filePath, 'content');
    fsModule.readFileSync = (candidatePath, ...args) => {
      if (candidatePath === filePath) {
        throw new Error('read failed');
      }
      return originalReadFileSync(candidatePath, ...args);
    };
    try {
      for (const transform of [transformers.csv, transformers.json]) {
        assert.throws(
          () => transform(filePath),
          (error) => error.name === 'ArgumentTypeError' &&
            error.message === `Could not read file '${filePath}': read failed`,
        );
      }
    } finally {
      fsModule.readFileSync = originalReadFileSync;
    }
  });
});

