const assert = require('node:assert/strict');
const test = require('node:test');

const {validators} = require(process.env.CANDIDATE_MODULE);

const errorMessage = 'Url or Uri must start with <scheme>://';

test('setUrl rejects every non-string input with the ordinary validation error', () => {
  const inputs = [
    undefined,
    null,
    true,
    42,
    42n,
    Symbol('url'),
    {},
    [],
    () => {},
  ];

  for (const input of inputs) {
    assert.throws(
      () => validators.setUrl(input),
      error => error instanceof Error &&
        error.name === 'Error' &&
        error.message === errorMessage,
      `unexpected error for ${String(input)}`,
    );
  }
});

test('setUrl does not invoke methods or coercion hooks on non-string inputs', () => {
  const input = {
    get match() {
      throw new Error('match must not be read');
    },
    [Symbol.toPrimitive]() {
      throw new Error('input must not be coerced');
    },
    toString() {
      throw new Error('toString must not be called');
    },
    valueOf() {
      throw new Error('valueOf must not be called');
    },
  };

  assert.throws(
    () => validators.setUrl(input),
    {name: 'Error', message: errorMessage},
  );
});

test('setUrl preserves the existing string acceptance policy', () => {
  const accepted = [
    'http://example.test',
    'custom+scheme://example.test',
    'prefix about:blank',
    'prefix data:text/plain,hello',
  ];

  for (const input of accepted) {
    assert.equal(validators.setUrl(input), undefined, input);
  }
});

test('setUrl still rejects strings without an accepted scheme pattern', () => {
  assert.throws(
    () => validators.setUrl('example.test/path'),
    {name: 'Error', message: errorMessage},
  );
});

