const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const {transformers} = require(process.env.CANDIDATE_MODULE);
const {ArgumentTypeError} = require(path.join(path.dirname(process.env.CANDIDATE_MODULE), 'node_modules', 'argparse'));

function withTempDirectory(callback) {
  const directory = fs.mkdtempSync(path.join(__dirname, 'cli-transformers-'));
  try {
    return callback(directory);
  } finally {
    fs.rmSync(directory, {recursive: true, force: true});
  }
}

function captureError(callback) {
  try {
    callback();
  } catch (error) {
    return error;
  }
  assert.fail('Expected callback to throw');
}

function assertJsonLiteralError(value) {
  const error = captureError(() => transformers.json(value));
  assert.match(error.message, /^The provided value must be a valid JSON\. Original error:/);
  assert.ok(error.cause instanceof SyntaxError);
}

test('CSV preserves literal parsing and parses regular files, including symlinks', () => {
  assert.deepStrictEqual(transformers.csv(' first, , second '), ['first', 'second']);

  withTempDirectory((directory) => {
    const file = path.join(directory, 'values.csv');
    const symlink = path.join(directory, 'values-link.csv');
    fs.writeFileSync(file, ' first, ,second\n\n third \r\n');
    fs.symlinkSync(file, symlink);

    assert.deepStrictEqual(transformers.csv(file), ['first', 'second', 'third']);
    assert.deepStrictEqual(transformers.csv(symlink), ['first', 'second', 'third']);
  });
});

test('JSON preserves literal parsing, file parsing, output, and parse causes', () => {
  assert.deepStrictEqual(transformers.json('{"enabled":true,"count":2}'), {enabled: true, count: 2});
  assertJsonLiteralError('{invalid');

  withTempDirectory((directory) => {
    const file = path.join(directory, 'values.json');
    const symlink = path.join(directory, 'values-link.json');
    const invalidFile = path.join(directory, 'invalid.json');
    fs.writeFileSync(file, '{"name":"from-file"}');
    fs.symlinkSync(file, symlink);
    fs.writeFileSync(invalidFile, '{invalid');

    assert.deepStrictEqual(transformers.json(file), {name: 'from-file'});
    assert.deepStrictEqual(transformers.json(symlink), {name: 'from-file'});

    const error = captureError(() => transformers.json(invalidFile));
    assert.match(error.message, new RegExp(`^'${invalidFile.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}' must be a valid JSON\\. Original error:`));
    assert.ok(error.cause instanceof SyntaxError);
  });
});

test('directories, dangling symlinks, and nonexistent paths use literal parsing', () => {
  withTempDirectory((directory) => {
    const existingDirectory = path.join(directory, 'directory');
    const directoryLink = path.join(directory, 'directory-link');
    const missing = path.join(directory, 'missing');
    const danglingLink = path.join(directory, 'dangling-link');
    fs.mkdirSync(existingDirectory);
    fs.symlinkSync(existingDirectory, directoryLink);
    fs.symlinkSync(path.join(directory, 'not-there'), danglingLink);

    for (const value of [existingDirectory, directoryLink, missing, danglingLink]) {
      assert.deepStrictEqual(transformers.csv(value), [value]);
      assertJsonLiteralError(value);
    }
  });
});

test('filesystem probe errors fall back to the literal-input parsers', () => {
  const originalStatSync = fs.statSync;
  fs.statSync = () => {
    throw new Error('probe failed');
  };

  try {
    assert.deepStrictEqual(transformers.csv('alpha, beta'), ['alpha', 'beta']);
    assert.deepStrictEqual(transformers.json('{"from":"literal"}'), {from: 'literal'});
  } finally {
    fs.statSync = originalStatSync;
  }
});

test('read failures after regular-file detection remain argparse errors for both transformers', () => {
  withTempDirectory((directory) => {
    const file = path.join(directory, 'read-failure');
    fs.writeFileSync(file, 'content');
    const originalReadFileSync = fs.readFileSync;
    const readError = new Error('simulated read failure');
    fs.readFileSync = (value, ...args) => {
      if (value === file) {
        throw readError;
      }
      return originalReadFileSync(value, ...args);
    };

    try {
      for (const transform of [transformers.csv, transformers.json]) {
        const error = captureError(() => transform(file));
        assert.ok(error instanceof ArgumentTypeError);
        assert.strictEqual(error.message, `Could not read file '${file}': ${readError.message}`);
      }
    } finally {
      fs.readFileSync = originalReadFileSync;
    }
  });
});

