    assertUrlError(value);
  }
});

test('setUrl rejects without reading methods or coercing the input', () => {
  let matchCalls = 0;
  const matchingObject = {
    match() {
      matchCalls += 1;
      return ['https://example.test'];
    },
  };
  assertUrlError(matchingObject);
  assert.equal(matchCalls, 0);

  const calls = [];
  const hostileInput = {
    get match() {
      calls.push('match');
      throw new Error('match accessed');
