describe('validators.setUrl', () => {
  test('rejects non-string primitives with the ordinary URL validation error', () => {
    for (const value of [undefined, null, false, true, 0, 1, 1n, Symbol('url')]) {
      assertInvalidUrl(value);
    }
  });

  test('rejects objects, boxed strings, and functions without invoking their methods', () => {
    let invoked = false;
    const values = [
      {match: () => {
        invoked = true;
        return ['https://example.test'];
      }},
      {toString: () => {
        invoked = true;
        return 'https://example.test';
      }},
      new String('https://example.test'),
      () => 'https://example.test',
    ];

    for (const value of values) {
      assertInvalidUrl(value);
    }
    assert.equal(invoked, false);
  });

  test('does not inspect properties on a non-string input', () => {
    let propertyRead = false;
    const value = new Proxy({}, {
      get() {
        propertyRead = true;
        throw new Error('input-owned property was read');
      },
    });

    assertInvalidUrl(value);
    assert.equal(propertyRead, false);
  });

  test('preserves the existing string acceptance policy and successful return value', () => {
    for (const value of [
      'https://example.test',
      'custom+scheme://resource',
      'about:blank',
      'data:text/plain,hello',
      'prefix about:blank',
      'prefix data:text/plain,hello',
    ]) {
      assert.equal(validators.setUrl(value), undefined);
    }
  });

  test('continues to reject strings outside the existing acceptance policy', () => {
    for (const value of ['', 'example.test', 'prefix https://example.test', 'ABOUT:blank']) {
      assertInvalidUrl(value);
    }
  });
});

