+test('CSV follows file symlinks and treats all other path states as literals', () => {
+  inTemporaryDirectory(() => {
+    const {transformers} = loadCandidate();
+    fs.writeFileSync('csv-target', 'from, symlink\nsecond,line');
+    fs.symlinkSync('csv-target', 'link,name');
+    fs.mkdirSync('directory,name');
+    fs.symlinkSync('directory,name', 'linked,directory');
+    fs.symlinkSync('missing-target', 'dangling,link');
+
+    assert.deepEqual(transformers.csv('link,name'), ['from', 'symlink', 'second', 'line']);
+    assert.deepEqual(transformers.csv('directory,name'), ['directory', 'name']);
+    assert.deepEqual(transformers.csv('linked,directory'), ['linked', 'directory']);
+    assert.deepEqual(transformers.csv('missing,path'), ['missing', 'path']);
+    assert.deepEqual(transformers.csv('dangling,link'), ['dangling', 'link']);
+  });
+});
+
+test('JSON follows file symlinks and treats all other path states as literals', () => {
+  inTemporaryDirectory(() => {
+    const {transformers} = loadCandidate();
+    fs.writeFileSync('json-target', '{"kind":"file-symlink"}');
+    fs.symlinkSync('json-target', '44');
+    fs.mkdirSync('45');
+    fs.symlinkSync('45', '46');
+    fs.symlinkSync('missing-target', '47');
+
+    assert.deepEqual(transformers.json('44'), {kind: 'file-symlink'});
