+test('read errors after regular-file detection remain argparse errors', () => {
+  inTemporaryDirectory(() => {
+    fs.writeFileSync('blocked.csv', 'unused');
+    fs.writeFileSync('blocked.json', '{}');
+    const {transformers} = loadCandidate({
+      readFileSync() {
+        throw new Error('simulated read failure');
+      },
+    });
+
+    assert.throws(
+      () => transformers.csv('blocked.csv'),
+      (error) => {
+        assert.ok(error instanceof ArgumentTypeError);
+        assert.equal(error.message, "Could not read file 'blocked.csv': simulated read failure");
+        return true;
+      },
+    );
+    assert.throws(
+      () => transformers.json('blocked.json'),
+      (error) => {
+        assert.ok(error instanceof ArgumentTypeError);
+        assert.equal(error.message, "Could not read file 'blocked.json': simulated read failure");
+        return true;
+      },
+    );
+  });
+});
