+test('JSON parse errors preserve literal and file messages with their causes', () => {
+  inTemporaryDirectory(() => {
+    const {transformers} = loadCandidate();
+    fs.writeFileSync('invalid.json', '{invalid');
+
+    assert.throws(
+      () => transformers.json('{invalid'),
+      (error) => {
+        assert.match(error.message, /^The provided value must be a valid JSON\. Original error: /);
+        assert.ok(error.cause instanceof SyntaxError);
+        assert.ok(error.message.endsWith(error.cause.message));
+        return true;
+      },
+    );
+    assert.throws(
+      () => transformers.json('invalid.json'),
+      (error) => {
+        assert.match(error.message, /^'invalid\.json' must be a valid JSON\. Original error: /);
+        assert.ok(error.cause instanceof SyntaxError);
+        assert.ok(error.message.endsWith(error.cause.message));
+        return true;
+      },
+    );
+  });
